/**
 * Track which icons a request used.
 *
 * @param string|null $name Icon name to register; null returns the list.
 * @return string[]
 */
function mnews_icons_used( $name = null ) {
	static $used = array();
	if ( null !== $name ) {
		$used[ $name ] = true;
	}
	return array_keys( $used );
}

/**
 * Log icons used while a cached fragment renders, so a cache hit can re-register them.
 *
 * @param string|null $name  Icon name to log.
 * @param bool        $reset Return the log and clear it.
 * @return string[]
 */
function mnews_icon_log( $name = null, $reset = false ) {
	static $log = array();
	if ( $reset ) {
		$out = array_keys( $log );
		$log = array();
		return $out;
	}
	if ( null !== $name ) {
		$log[ $name ] = true;
	}
	return array_keys( $log );
}

/**
 * Echo an icon.
 *
 * @param string $name Icon key from mnews_icon_paths().
 * @param int    $size Pixel size (width and height).
 */
function mnews_icon( $name, $size = 20 ) {
	$paths = mnews_icon_paths();
	if ( ! isset( $paths[ $name ] ) ) {
		return;
	}
	mnews_icons_used( $name );
	mnews_icon_log( $name );
	printf(
		'<svg class="mnw-icon" width="%1$d" height="%1$d" aria-hidden="true" focusable="false"><use href="#mnw-i-%2$s"></use></svg>',
		(int) $size,
		esc_attr( $name )
	);
}

/**
 * Print the sprite with only the used symbols, once, at the end of the page.
 */
function mnews_print_sprite() {
	$used = mnews_icons_used();
	if ( empty( $used ) ) {
		return;
	}
	$paths = mnews_icon_paths();
	echo '<svg width="0" height="0" style="position:absolute" aria-hidden="true" focusable="false"><defs>';
	foreach ( $used as $name ) {
		// Markup comes from the static map above, never from user input.
		printf( '<symbol id="mnw-i-%1$s" viewBox="0 0 24 24">%2$s</symbol>', esc_attr( $name ), $paths[ $name ] ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped
	}
	echo '</defs></svg>';
}
add_action( 'wp_footer', 'mnews_print_sprite', 5 );
